1 João 4 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Por que os leitores não devem crer em qualquer espírito?","o":["Porque muitos falsos profetas já apareceram no mundo","Porque o Dia do Juízo está próximo","Porque os espíritos não podem ser provados","Porque o mundo odeia os filhos de Deus"],"c":0,"v":1,"e":"O versículo 1 diz que se deve provar os espíritos, pois muitos falsos profetas já apareceram no mundo."},
 {"t":"multipla","p":"Como se reconhece o Espírito de Deus?","o":["Ele faz sinais e maravilhas","Ele confessa que Jesus Cristo veio em carne","Ele fala como o mundo fala","Ele é ouvido por todos"],"c":1,"v":2,"e":"O versículo 2 diz que todo espírito que confessa que Jesus Cristo veio em carne é de Deus."},
 {"t":"multipla","p":"Por que os filhinhos já derrotaram os falsos profetas?","o":["Porque conhecem toda a Lei","Porque são mais numerosos que eles","Porque maior é aquele que está neles do que aquele que está no mundo","Porque o mundo não escuta os falsos profetas"],"c":2,"v":4,"e":"O versículo 4 explica que maior é aquele que está neles do que aquele que está no mundo."},
 {"t":"multipla","p":"Por que aquele que não ama não conhece a Deus?","o":["Porque não guarda os mandamentos","Porque não viu a Deus","Porque não confessa o Filho","Porque Deus é amor"],"c":3,"v":8,"e":"O versículo 8 diz que quem não ama não conhece a Deus, pois Deus é amor."},
 {"t":"multipla","p":"Em que consiste o amor, segundo o capítulo?","o":["Em que nós amamos a Deus de todo o coração","Em que Deus nos amou e enviou seu Filho como propiciação pelos nossos pecados","Em que vencemos o mundo","Em que não temos medo do Dia do Juízo"],"c":1,"v":10,"e":"O versículo 10 diz que o amor não é que tenhamos amado a Deus, mas que Ele nos amou e enviou seu Filho como propiciação pelos nossos pecados."},
 {"t":"cv","p":"O capítulo afirma que o Pai enviou seu Filho como Salvador do mundo.","c":true,"v":14,"e":"O versículo 14 diz que nós temos visto e testificado que o Pai enviou seu Filho como Salvador do mundo."},
 {"t":"cv","p":"Segundo o capítulo, nós amamos a Deus primeiro, e por isso Ele passou a nos amar.","c":false,"v":19,"e":"O versículo 19 diz o contrário: nós o amamos porque Ele nos amou primeiro."},
 {"t":"cv","p":"Quem diz amar a Deus, mas odeia seu irmão, é chamado de mentiroso.","c":true,"v":20,"e":"O versículo 20 diz que quem afirma amar a Deus e odeia seu irmão é um mentiroso."}
]}

1 João 5 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Como o capítulo descreve os mandamentos de Deus?","o":["São muitos","Não são pesados","São difíceis de cumprir","Foram escritos em pedra"],"c":1,"v":3,"e":"O versículo 3 diz que os mandamentos de Deus não são pesados."},
 {"t":"multipla","p":"Qual é a vitória que vence o mundo?","o":["A nossa fé","O nosso amor","A nossa obediência","A nossa esperança"],"c":0,"v":4,"e":"O versículo 4 diz que a vitória que vence o mundo é a nossa fé."},
 {"t":"multipla","p":"Por meio de que, segundo o texto, Jesus Cristo veio?","o":["Fogo e vento","Pão e vinho","Água e sangue","Luz e glória"],"c":2,"v":6,"e":"O versículo 6 diz que Jesus Cristo veio por meio de água e sangue."},
 {"t":"multipla","p":"Onde está a vida eterna que Deus nos concedeu?","o":["Na lei","Nos profetas","No templo","Em seu Filho"],"c":3,"v":11,"e":"O versículo 11 diz que a vida eterna está no Filho de Deus."},
 {"t":"multipla","p":"Por que o autor escreveu estas coisas aos que creem no nome do Filho de Deus?","o":["Para que saibam que têm a vida eterna","Para corrigir falsos mestres","Para anunciar sua visita","Para pedir ofertas"],"c":0,"v":13,"e":"O versículo 13 diz que ele escreveu para que saibam que têm a vida eterna."},
 {"t":"cv","p":"Deus nos ouve quando pedimos alguma coisa conforme a sua vontade.","c":true,"v":14,"e":"O versículo 14 diz que, se pedirmos algo conforme a sua vontade, ele nos ouve."},
 {"t":"cv","p":"Segundo o capítulo, apenas uma parte do mundo jaz sob o domínio do maligno.","c":false,"v":19,"e":"O versículo 19 diz que todo o mundo jaz sob o domínio do maligno."},
 {"t":"cv","p":"O capítulo termina com a exortação: \"Filhinhos, guardem-se dos ídolos\".","c":true,"v":21,"e":"O versículo 21, o último do capítulo, traz essa exortação."}
]}

1 João 1 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Segundo o autor, o que eles ouviram, viram e tocaram com as mãos?","o":["A Palavra da vida","A arca da aliança","As tábuas da lei","O templo de Jerusalém"],"c":0,"v":1,"e":"No versículo 1, o autor diz que ouviram, viram, contemplaram e tocaram com as mãos a Palavra da vida."},
 {"t":"multipla","p":"Por que o autor anuncia o que viu e ouviu?","o":["Para que os leitores fujam do mundo","Para que os leitores evitem falsos mestres","Para que os leitores tenham comunhão com eles","Para que os leitores guardem o sábado"],"c":2,"v":3,"e":"O versículo 3 diz que o anúncio é feito para que os leitores mantenham comunhão com eles."},
 {"t":"multipla","p":"Qual o motivo dado para escrever estas coisas?","o":["Para que os leitores não tenham medo","Para que a alegria deles seja completa","Para que ninguém seja enganado","Para que a igreja cresça em número"],"c":1,"v":4,"e":"O versículo 4 diz que escrevem para que a alegria deles seja completa."},
 {"t":"multipla","p":"Qual é a mensagem que eles ouviram e anunciam?","o":["Deus é amor e perdoa tudo","Deus é fogo que consome","Deus é rei sobre toda a terra","Deus é luz, e nele não há treva nenhuma"],"c":3,"v":5,"e":"O versículo 5 apresenta a mensagem: Deus é luz, e nele não há treva nenhuma."},
 {"t":"multipla","p":"Segundo o texto, o que nos purifica de todo pecado quando andamos na luz?","o":["O jejum e a oração","A lei de Moisés","O sangue de Jesus Cristo, seu Filho","As boas obras"],"c":2,"v":7,"e":"O versículo 7 diz que o sangue de Jesus Cristo, seu Filho, nos purifica de todo pecado."},
 {"t":"cv","p":"Se dissermos que temos comunhão com Deus e andarmos nas trevas, mentimos.","c":true,"v":6,"e":"O versículo 6 diz que, nesse caso, mentimos e não praticamos a verdade."},
 {"t":"cv","p":"Quem diz que não tem pecado nenhum mostra que a verdade habita nele.","c":false,"v":8,"e":"O versículo 8 diz o contrário: quem diz isso engana a si mesmo, e a verdade não habita nele."},
 {"t":"cv","p":"Se confessarmos os nossos pecados, Deus é fiel e justo para nos perdoar.","c":true,"v":9,"e":"O versículo 9 afirma que Ele é fiel e justo para perdoar os pecados e purificar de toda injustiça."}
]}

1 João 2 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Quem é o nosso Advogado junto ao Pai, se alguém pecar?","o":["O apóstolo João","Moisés","Jesus Cristo, o Justo","O anjo do Senhor"],"c":2,"v":1,"e":"O versículo 1 diz que temos um Advogado junto ao Pai, Jesus Cristo, o Justo."},
 {"t":"multipla","p":"Como é chamado quem diz \"Eu o conheço\" mas não guarda os mandamentos?","o":["Mentiroso","Fraco na fé","Filhinho","Anticristo"],"c":0,"v":4,"e":"O versículo 4 diz que essa pessoa é mentirosa e a verdade não está nela."},
 {"t":"multipla","p":"Por que quem odeia o irmão não sabe para onde vai?","o":["Porque saiu do grupo","Porque não conhece o Pai","Porque ama o mundo","Porque as trevas lhe cegaram os olhos"],"c":3,"v":11,"e":"O versículo 11 diz que ele não sabe para onde vai porque as trevas lhe cegaram os olhos."},
 {"t":"multipla","p":"Por que João escreve aos jovens no versículo 13?","o":["Porque conhecem o Pai","Porque venceram o maligno","Porque seus pecados são perdoados","Porque têm a unção"],"c":1,"v":13,"e":"No versículo 13, João escreve aos jovens porque venceram o maligno."},
 {"t":"multipla","p":"O que o capítulo diz que há no mundo e não procede do Pai?","o":["A pobreza, a doença e a morte","A guerra, a fome e a peste","A concupiscência da carne, a dos olhos e a soberba da vida","O ódio, a mentira e a inveja"],"c":2,"v":16,"e":"O versículo 16 cita a concupiscência da carne, a concupiscência dos olhos e a soberba da vida."},
 {"t":"cv","p":"Segundo o capítulo, o mundo passa, mas quem faz a vontade de Deus permanece eternamente.","c":true,"v":17,"e":"O versículo 17 diz que o mundo passa e que quem faz a vontade de Deus permanece eternamente."},
 {"t":"cv","p":"Segundo o capítulo, quem nega o Filho ainda tem o Pai.","c":false,"v":23,"e":"O versículo 23 diz que quem nega o Filho não tem o Pai."},
 {"t":"cv","p":"O capítulo afirma que todo aquele que pratica a justiça é nascido d'Ele.","c":true,"v":29,"e":"O versículo 29 diz que todo aquele que pratica a justiça é nascido d'Ele."}
]}

1 João 3 Â· exercÃ­cios.texto:
{"perguntas":[
{"t":"multipla","p":"Por que o mundo não nos conhece?","o":["Porque não somos deste mundo","Porque não o conheceu a Ele mesmo","Porque ainda não nos manifestamos","Porque o mundo é do diabo"],"c":1,"v":1,"e":"O versículo 1 diz que o mundo não nos conhece porque não conheceu a Ele."},
{"t":"multipla","p":"O que acontecerá quando Ele se manifestar?","o":["Seremos julgados por nossas obras","O mundo finalmente nos conhecerá","Seremos semelhantes a Ele","Receberemos uma nova lei"],"c":2,"v":2,"e":"O versículo 2 diz que seremos semelhantes a Ele, porque O veremos como Ele é."},
{"t":"multipla","p":"Para que o Filho de Deus se manifestou, segundo o versículo 8?","o":["Para destruir as obras do diabo","Para dar uma nova lei","Para julgar o mundo","Para chamar os justos"],"c":0,"v":8,"e":"O versículo 8 diz que o Filho de Deus se manifestou para destruir as obras do diabo."},
{"t":"multipla","p":"Por que Caim assassinou seu irmão?","o":["Porque o irmão o enganou","Porque Deus rejeitou sua oferta","Porque queria a herança do irmão","Porque suas obras eram más e as do irmão, justas"],"c":3,"v":12,"e":"O versículo 12 diz que as obras de Caim eram más, enquanto as de seu irmão eram justas."},
{"t":"multipla","p":"Como conhecemos o amor?","o":["Pela lei que recebemos","Pelo amor dos irmãos por nós","Porque Cristo deu a Sua vida por nós","Pelas palavras dos profetas"],"c":2,"v":16,"e":"O versículo 16 diz que conhecemos o amor porque Cristo deu a Sua vida por nós."},
{"t":"cv","p":"O capítulo pede que amemos não só em palavras, mas em ações e na verdade.","c":true,"v":18,"e":"O versículo 18 diz que não amemos apenas em palavras ou pela língua, mas em ações e na verdade."},
{"t":"cv","p":"Se o nosso coração nos condena, Deus é maior do que o nosso coração e conhece todas as coisas.","c":true,"v":20,"e":"É exatamente o que diz o versículo 20."},
{"t":"cv","p":"Conhecemos que Deus permanece em nós pelos sinais que vemos no céu.","c":false,"v":24,"e":"O versículo 24 diz que conhecemos isso pelo Espírito que Ele nos deu."}
]}
